struct TimeMap {
    private var store: [String: [(t: Int, v: String)]] = [:]
    mutating func set(_ key: String, _ value: String, _ timestamp: Int) {
        store[key, default: []].append((timestamp, value))
    }
    func get(_ key: String, _ timestamp: Int) -> String {
        guard let list = store[key] else { return "" }
        var lo = 0, hi = list.count          // first index with t > timestamp
        while lo < hi {
            let mid = (lo + hi) / 2
            if list[mid].t <= timestamp { lo = mid + 1 } else { hi = mid }
        }
        return lo == 0 ? "" : list[lo - 1].v
    }
}
